//! Capability registry, channel ceilings and fail-closed profile narrowing.
//!
//! Every Responses feature that a channel may or may not be able to serve has
//! one [`Capability`] id. A channel adapter declares its *ceiling*: what the
//! adapter implements. An operator may load a capability profile (for example
//! one generated by `tools/upstream-capability-probe`) that *narrows* the
//! ceiling. The effective set is the intersection:
//!
//! ```text
//! enabled = ceiling says supported AND profile says supported (if a profile is loaded)
//!           AND every dependency is enabled
//! ```
//!
//! `unsupported`, `unknown` and absent entries all disable a capability. A
//! profile can never enable something the adapter lacks.

use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap};

/// Value of the profile document's `format` field.
pub const PROFILE_FORMAT: &str = "responses-capability-profile";
/// Supported profile document schema version.
pub const PROFILE_SCHEMA_VERSION: u32 = 1;

/// One gated feature of the Responses API.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Capability {
    Text,
    Streaming,
    NonStreaming,
    ImageInput,
    FileInput,
    FunctionTools,
    ToolChoice,
    CustomTools,
    WebSearch,
    FileSearch,
    CodeInterpreter,
    Mcp,
    ImageGeneration,
    ComputerUse,
    Shell,
    Reasoning,
    StructuredOutput,
    Verbosity,
    SamplingControls,
    MaxOutputTokens,
    Logprobs,
    StoredResponses,
    PreviousResponse,
    Conversations,
    Background,
    StreamResume,
    AutoTruncation,
    Compaction,
    PromptTemplates,
    ExactUsage,
}

impl Capability {
    /// Every capability, in registry order.
    pub const ALL: [Capability; 30] = [
        Self::Text,
        Self::Streaming,
        Self::NonStreaming,
        Self::ImageInput,
        Self::FileInput,
        Self::FunctionTools,
        Self::ToolChoice,
        Self::CustomTools,
        Self::WebSearch,
        Self::FileSearch,
        Self::CodeInterpreter,
        Self::Mcp,
        Self::ImageGeneration,
        Self::ComputerUse,
        Self::Shell,
        Self::Reasoning,
        Self::StructuredOutput,
        Self::Verbosity,
        Self::SamplingControls,
        Self::MaxOutputTokens,
        Self::Logprobs,
        Self::StoredResponses,
        Self::PreviousResponse,
        Self::Conversations,
        Self::Background,
        Self::StreamResume,
        Self::AutoTruncation,
        Self::Compaction,
        Self::PromptTemplates,
        Self::ExactUsage,
    ];

    /// Stable wire id used in profiles, logs and error messages.
    pub fn id(self) -> &'static str {
        match self {
            Self::Text => "text",
            Self::Streaming => "streaming",
            Self::NonStreaming => "non_streaming",
            Self::ImageInput => "image_input",
            Self::FileInput => "file_input",
            Self::FunctionTools => "function_tools",
            Self::ToolChoice => "tool_choice",
            Self::CustomTools => "custom_tools",
            Self::WebSearch => "web_search",
            Self::FileSearch => "file_search",
            Self::CodeInterpreter => "code_interpreter",
            Self::Mcp => "mcp",
            Self::ImageGeneration => "image_generation",
            Self::ComputerUse => "computer_use",
            Self::Shell => "shell",
            Self::Reasoning => "reasoning",
            Self::StructuredOutput => "structured_output",
            Self::Verbosity => "verbosity",
            Self::SamplingControls => "sampling_controls",
            Self::MaxOutputTokens => "max_output_tokens",
            Self::Logprobs => "logprobs",
            Self::StoredResponses => "stored_responses",
            Self::PreviousResponse => "previous_response",
            Self::Conversations => "conversations",
            Self::Background => "background",
            Self::StreamResume => "stream_resume",
            Self::AutoTruncation => "auto_truncation",
            Self::Compaction => "compaction",
            Self::PromptTemplates => "prompt_templates",
            Self::ExactUsage => "exact_usage",
        }
    }

    /// Parse a wire id; `None` for ids this build does not know.
    pub fn from_id(id: &str) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|capability| capability.id() == id)
    }

    /// Capabilities that must also be enabled for this one to be usable.
    pub fn dependencies(self) -> &'static [Capability] {
        match self {
            Self::ToolChoice => &[Self::FunctionTools],
            Self::PreviousResponse | Self::Background => &[Self::StoredResponses],
            Self::StreamResume => &[Self::Streaming, Self::StoredResponses],
            _ => &[],
        }
    }

    /// Whether this version of the engine can represent the capability on the
    /// wire. Hosted tool items, logprobs, structured-output schemas,
    /// background jobs, stream resumption and similar features have no
    /// request or event representation yet, so no channel can enable them.
    pub fn engine_supported(self) -> bool {
        matches!(
            self,
            Self::Text
                | Self::Streaming
                | Self::NonStreaming
                | Self::ImageInput
                | Self::FileInput
                | Self::FunctionTools
                | Self::ToolChoice
                | Self::Reasoning
                | Self::Verbosity
                | Self::SamplingControls
                | Self::MaxOutputTokens
                | Self::StoredResponses
                | Self::PreviousResponse
                | Self::ExactUsage
        )
    }
}

impl Serialize for Capability {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(self.id())
    }
}

/// Declared support level.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Support {
    Supported,
    Unsupported,
    Unknown,
}

/// Which layer provides a capability.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Provider {
    /// The upstream model or service does it natively.
    Upstream,
    /// The proxy implements it locally on top of the upstream.
    Proxy,
    /// Nothing provides it.
    #[default]
    None,
}

/// One capability's declaration.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CapabilityStatus {
    pub support: Support,
    #[serde(default)]
    pub provider: Provider,
    /// Short implementation tag, for example `collected_stream`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<String>,
    /// Probe ids or a short note backing the declaration.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub evidence: Option<String>,
}

impl CapabilityStatus {
    pub fn supported(provider: Provider, mode: &str) -> Self {
        Self {
            support: Support::Supported,
            provider,
            mode: Some(mode.to_string()),
            evidence: None,
        }
    }

    pub fn unsupported(reason: &str) -> Self {
        Self {
            support: Support::Unsupported,
            provider: Provider::None,
            mode: Some(reason.to_string()),
            evidence: None,
        }
    }
}

/// A channel's capability declarations, keyed by capability.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CapabilitySet {
    channel: String,
    entries: BTreeMap<Capability, CapabilityStatus>,
}

impl CapabilitySet {
    pub fn new(channel: impl Into<String>) -> Self {
        Self {
            channel: channel.into(),
            entries: BTreeMap::new(),
        }
    }

    pub fn with(mut self, capability: Capability, status: CapabilityStatus) -> Self {
        self.entries.insert(capability, status);
        self
    }

    pub fn channel(&self) -> &str {
        &self.channel
    }

    pub fn status(&self, capability: Capability) -> Support {
        self.entries
            .get(&capability)
            .map(|status| status.support)
            .unwrap_or(Support::Unknown)
    }

    pub fn entry(&self, capability: Capability) -> Option<&CapabilityStatus> {
        self.entries.get(&capability)
    }

    /// True only when the capability and all of its dependencies are
    /// declared supported.
    pub fn enabled(&self, capability: Capability) -> bool {
        self.status(capability) == Support::Supported
            && capability
                .dependencies()
                .iter()
                .all(|dependency| self.enabled(*dependency))
    }

    /// Every enabled capability, in registry order.
    pub fn enabled_ids(&self) -> Vec<&'static str> {
        Capability::ALL
            .into_iter()
            .filter(|capability| self.enabled(*capability))
            .map(Capability::id)
            .collect()
    }

    /// Disable capabilities this engine version cannot represent, whatever
    /// the channel declares. Returns the ids that were disabled.
    pub fn restrict_to_engine(&mut self) -> Vec<&'static str> {
        let mut masked = Vec::new();
        for (capability, status) in self.entries.iter_mut() {
            if status.support == Support::Supported && !capability.engine_supported() {
                status.support = Support::Unsupported;
                status.mode = Some("not_implemented_by_engine".into());
                masked.push(capability.id());
            }
        }
        masked
    }

    /// Narrow this ceiling with an operator profile.
    ///
    /// Returns non-fatal warnings (unknown ids, attempts to enable
    /// capabilities the adapter does not implement). A profile written for a
    /// different channel is an error: silently applying it could hide a
    /// misconfiguration.
    pub fn narrow(&mut self, document: &ProfileDocument) -> Result<Vec<String>, ProfileError> {
        if document.channel != self.channel {
            return Err(ProfileError(format!(
                "capability profile is for channel '{}', but the active channel is '{}'",
                document.channel, self.channel
            )));
        }
        let mut warnings = Vec::new();
        let mut unknown: Vec<&String> = document
            .capabilities
            .keys()
            .filter(|id| Capability::from_id(id).is_none())
            .collect();
        unknown.sort();
        for id in unknown {
            warnings.push(format!("ignoring unknown capability id '{id}'"));
        }
        for capability in Capability::ALL {
            let ceiling = self.status(capability);
            let declared = document.capabilities.get(capability.id());
            if let Some(declared) = declared {
                if declared.support == Support::Supported && ceiling != Support::Supported {
                    warnings.push(format!(
                        "profile marks '{}' supported, but channel '{}' does not implement it; it stays disabled",
                        capability.id(),
                        self.channel
                    ));
                }
            }
            if ceiling != Support::Supported {
                continue;
            }
            let entry = self
                .entries
                .get_mut(&capability)
                .expect("supported capabilities have an entry");
            match declared.map(|status| status.support) {
                Some(Support::Supported) => {
                    if let Some(evidence) = declared.and_then(|status| status.evidence.clone()) {
                        entry.evidence = Some(evidence);
                    }
                }
                Some(support) => {
                    entry.support = support;
                    entry.mode = Some("narrowed_by_profile".into());
                }
                None => {
                    entry.support = Support::Unknown;
                    entry.mode = Some("absent_from_profile".into());
                }
            }
        }
        Ok(warnings)
    }
}

/// A capability profile could not be loaded or applied.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProfileError(pub String);

impl std::fmt::Display for ProfileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for ProfileError {}

/// Operator-supplied profile document (`format: responses-capability-profile`).
///
/// Unknown top-level fields such as `generated_by` are ignored.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct ProfileDocument {
    pub format: String,
    pub schema_version: u32,
    pub channel: String,
    #[serde(default)]
    pub capabilities: HashMap<String, CapabilityStatus>,
}

impl ProfileDocument {
    pub fn parse(bytes: &[u8]) -> Result<Self, ProfileError> {
        let document: Self = serde_json::from_slice(bytes)
            .map_err(|error| ProfileError(format!("invalid capability profile: {error}")))?;
        if document.format != PROFILE_FORMAT {
            return Err(ProfileError(format!(
                "capability profile format must be '{PROFILE_FORMAT}'"
            )));
        }
        if document.schema_version != PROFILE_SCHEMA_VERSION {
            return Err(ProfileError(format!(
                "unsupported capability profile schema_version {}; expected {PROFILE_SCHEMA_VERSION}",
                document.schema_version
            )));
        }
        Ok(document)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    fn ceiling() -> CapabilitySet {
        CapabilitySet::new("test_channel")
            .with(
                Capability::Text,
                CapabilityStatus::supported(Provider::Upstream, "native"),
            )
            .with(
                Capability::Streaming,
                CapabilityStatus::supported(Provider::Proxy, "reencoded"),
            )
            .with(
                Capability::FunctionTools,
                CapabilityStatus::supported(Provider::Proxy, "dialect"),
            )
            .with(
                Capability::ToolChoice,
                CapabilityStatus::supported(Provider::Proxy, "prompted"),
            )
            .with(
                Capability::StoredResponses,
                CapabilityStatus::supported(Provider::Proxy, "sqlite"),
            )
            .with(
                Capability::PreviousResponse,
                CapabilityStatus::supported(Provider::Proxy, "transcript"),
            )
            .with(
                Capability::Background,
                CapabilityStatus::unsupported("not_implemented"),
            )
    }

    fn document(entries: &[(&str, &str)]) -> ProfileDocument {
        let capabilities: serde_json::Map<String, serde_json::Value> = entries
            .iter()
            .map(|(id, support)| ((*id).to_string(), serde_json::json!({"support": support})))
            .collect();
        ProfileDocument::parse(
            serde_json::json!({
                "format": PROFILE_FORMAT,
                "schema_version": 1,
                "channel": "test_channel",
                "capabilities": capabilities,
                "generated_by": {"tool": "test"}
            })
            .to_string()
            .as_bytes(),
        )
        .unwrap()
    }

    #[test]
    fn ids_round_trip_and_are_unique() {
        let mut seen = HashSet::new();
        for capability in Capability::ALL {
            assert_eq!(Capability::from_id(capability.id()), Some(capability));
            assert!(seen.insert(capability.id()));
            assert_eq!(
                serde_json::to_value(capability).unwrap(),
                serde_json::json!(capability.id())
            );
        }
        assert_eq!(Capability::from_id("teleport"), None);
    }

    #[test]
    fn undeclared_capabilities_and_missing_dependencies_are_disabled() {
        let set = ceiling();
        assert!(set.enabled(Capability::Text));
        assert!(!set.enabled(Capability::Mcp), "undeclared fails closed");
        assert!(!set.enabled(Capability::Background));
        let without_tools = CapabilitySet::new("c").with(
            Capability::ToolChoice,
            CapabilityStatus::supported(Provider::Proxy, "prompted"),
        );
        assert!(
            !without_tools.enabled(Capability::ToolChoice),
            "tool_choice needs function_tools"
        );
    }

    #[test]
    fn profile_only_narrows_the_ceiling() {
        let mut set = ceiling();
        let warnings = set
            .narrow(&document(&[
                ("text", "supported"),
                ("streaming", "unsupported"),
                ("function_tools", "unknown"),
                ("stored_responses", "supported"),
                ("previous_response", "supported"),
                ("background", "supported"),
                ("teleport", "supported"),
            ]))
            .unwrap();
        assert!(set.enabled(Capability::Text));
        assert!(!set.enabled(Capability::Streaming));
        assert!(!set.enabled(Capability::FunctionTools));
        assert!(
            !set.enabled(Capability::ToolChoice),
            "absent from profile and its dependency is off"
        );
        assert!(set.enabled(Capability::PreviousResponse));
        assert!(
            !set.enabled(Capability::Background),
            "a profile cannot enable an unimplemented capability"
        );
        assert!(warnings.iter().any(|w| w.contains("'teleport'")));
        assert!(warnings.iter().any(|w| w.contains("'background'")));
        assert_eq!(
            set.entry(Capability::Streaming).unwrap().mode.as_deref(),
            Some("narrowed_by_profile")
        );
    }

    #[test]
    fn profile_for_another_channel_is_rejected() {
        let mut set = ceiling();
        let mut doc = document(&[("text", "supported")]);
        doc.channel = "other".into();
        assert!(set.narrow(&doc).is_err());
    }

    #[test]
    fn parse_rejects_wrong_format_and_version() {
        let bad_format =
            serde_json::json!({"format": "probe", "schema_version": 1, "channel": "c"});
        assert!(ProfileDocument::parse(bad_format.to_string().as_bytes()).is_err());
        let bad_version =
            serde_json::json!({"format": PROFILE_FORMAT, "schema_version": 9, "channel": "c"});
        assert!(ProfileDocument::parse(bad_version.to_string().as_bytes()).is_err());
        assert!(ProfileDocument::parse(b"not json").is_err());
    }

    #[test]
    fn engine_masks_capabilities_it_cannot_represent() {
        let mut set = ceiling().with(
            Capability::WebSearch,
            CapabilityStatus::supported(Provider::Upstream, "native"),
        );
        let masked = set.restrict_to_engine();
        assert_eq!(masked, vec!["web_search"]);
        assert!(!set.enabled(Capability::WebSearch));
        assert!(set.enabled(Capability::Text));
    }
}
